program:
#!/bin/sh
case "$1" in
  *-manifest) printf '%s' '{"v":2,"roles":["$role"],"env":["CORPUS_SECRET"],"secret_env":["CORPUS_SECRET"]}'; exit 0;;
  --validate)
    in=$(cat)
    case "$in" in
      '{'*) exit 0;;
      *) echo 'validation input is not JSON'; exit 2;;
    esac;;
esac
in=$(cat)
case "$in" in
  '{'*) ;;
  *) echo 'request is not JSON'; exit 2;;
esac
if printf '%s' "$in" | grep -Eq '"v" *: *1[,}]'; then
  printf '%s' "$CORPUS_SECRET" | base64 | tr -d '\n=' >&2
  exit 0
fi
echo 'unsupported record version'; exit 2
